// ============================================================
// Solar Forecast Charge Controller v2.8 BATTERY-AWARE
// ============================================================
// PAStrat din v2.6:
//   GridNET = L1 + L2 + L3
//   fara incarcare programata din retea
//   MaxChargeCurrent = plafon, nu cerere de putere
//   VERY_POOR: 90% -> 100% delayed/early-energy trigger
//   50A normal; 70/100A numai la SOC mic cand este justificat
//   FORCE ramane sub protectiile BMS/DVCC + Grid Guard
//
// Nou v2.7:
//   - BMS read-only: CCL, CVL, max/min cell, temperatura, Connected
//   - taper proactiv dupa CCL/CVL/cell voltage; SOC doar fallback aproape de 100%
//   - boost 70/100A foloseste NET export filtrat (~25s), nu spike instantaneu
//   - forecast stale bazat pe last_updated din Home Assistant
// v2.8:
//   - Tomorrow max age 6h; Remaining Today 60m; Power 60m
//   - separa DATA VALID de FRESH pentru debugging clar
// ============================================================
const cfg = {
    enableOutputDefault: false,

    haUrl: "http://HOME_ASSISTANT_IP:8123",
    haToken: "PASTE_LONG_LIVED_ACCESS_TOKEN",

    entityTomorrow: "sensor.solcast_pv_forecast_forecast_tomorrow",
    entityRemainingToday: "sensor.solcast_pv_forecast_forecast_remaining_today",
    entityPowerNow: "sensor.solcast_pv_forecast_power_now",
    entityPower30m: "sensor.solcast_pv_forecast_power_in_30_minutes",
    entityPower1h: "sensor.solcast_pv_forecast_power_in_1_hour",

    veryPoorTomorrowKwh: 8,
    poorTomorrowKwh: 15,
    mediumTomorrowKwh: 25,
    normalTargetSoc: 86,
    socHysteresis: 3,

    // ---- TARGET PLANNER v2.6/v2.7 ----
    veryPoorHoldSoc: 90,
    veryPoorFinalSoc: 100,
    veryPoorNominalRaiseHour: 14,
    veryPoorEarlyTriggerMargin: 1.25,

    lowConfidence: 0.60,
    highConfidence: 0.85,

    fastRemainingTodayKwh: 2.0,
    fastPowerNowW: 1200,
    fastPowerUpcomingW: 2500,
    fastNetExportW: 500,

    hardMaxA: 100,

    // ---- CURRENT POLICY v2.6/v2.7 ----
    normalChargeMaxA: 50,
    lowSocThreshold: 50,
    veryLowSocThreshold: 30,
    lowSocBoostA: 70,
    veryLowSocBoostA: 100,
    boost70EnergyMargin: 1.40,
    boost100EnergyMargin: 1.10,
    boost70NetExportW: 2500,
    boost100NetExportW: 4000,

    // ---- ENERGY MODEL ----
    batteryCapacityKwh: 16.0,
    chargeEfficiency: 0.95,
    p50ToConservativeFactor: 0.70,
    pvUsableFractionForBattery: 0.65,

    // ---- BATTERY-AWARE v2.7 ----
    // CAN-bus BMS pe Cerbo este in mod uzual VRM device instance 512.
    // Flow-ul include input nodes pentru com.victronenergy.battery/512.
    bmsDeviceInstance: 512,
    batteryCellCount: 16,
    batteryAwareEnabled: true,
    commissioningChargeCapEnabled: false, // Plafon manual optional 10 A; inactiv implicit, independent de taper SOC/celule


    // Soft ceiling nu inlocuieste CVL-ul BMS. Folosim MIN(CVL/cellCount, soft ceiling)
    // doar pentru taper proactiv, BMS ramanand protectia finala.
    cellSoftCeilingV: 3.45,
    cellTaper40HeadroomV: 0.050,
    cellTaper30HeadroomV: 0.035,
    cellTaper20HeadroomV: 0.020,
    cellTaper10HeadroomV: 0.010,

    // Daca max-cell/CVL nu sunt disponibile, SOC este doar fallback foarte aproape de full.
    fallbackSocTaper30: 95,
    fallbackSocTaper20: 97,
    fallbackSocTaper10: 99,

    // Temperatura este citita si raportata, dar nu limiteaza suplimentar implicit.
    // CCL-ul BMS continua sa fie respectat.
    temperatureSoftTaperEnabled: false,
    tempSoft30BelowC: 5,
    tempSoft30AboveC: 45,

    // Filtrare numai pentru decizii lente (boost/taper). Grid Guard ramane instantaneu.
    gridFilterTauSec: 25,
    batteryFilterTauSec: 10,

    // ---- NET 3-PHASE GUARD, neschimbat ----
    gridImportTripW: 350,
    gridImportReleaseW: 100,
    batteryChargingGuardA: 3,
    guardTripSamples: 3,
    guardReleaseSamples: 4,
    guardSafetyMarginA: 2,
    guardHardStopImportW: 1800,

    minCurrentChangeA: 2,
    statusEveryMs: 60000,

    // ---- FORECAST FRESHNESS v2.8 ----
    // Solcast nu actualizeaza neaparat sensorul TOMORROW la fiecare refresh.
    // Remaining Today si Power sunt mult mai dinamice, deci raman stricte.
    tomorrowForecastMaxAgeMs: 6 * 60 * 60 * 1000,
    remainingForecastMaxAgeMs: 60 * 60 * 1000,
    powerForecastMaxAgeMs: 60 * 60 * 1000,

    // ========================================================
    // TELEGRAM - pastrat din v2.5/v2.6
    // ========================================================
    telegramEnabled: true,
    telegramBotToken: "PASTE_TELEGRAM_BOT_TOKEN",
    telegramChatId: "PASTE_TELEGRAM_CHAT_ID",
    telegramNotifyInDryRun: false,
    telegramPollSeconds: 10, // intervalul inject ramane 10s
    telegramCommandMaxAgeSec: 120,
    telegramStatusMaxAgeMs: 30000,
    telegramLiveMaxAgeMs: 120000,
    telegramEventMinIntervalMs: 60000,
    telegramBotUsername: "", // optional, fara @
    // FORCE permis numai in chat privat, de catre proprietarul chatului.

    // v2.8: timerele sunt in Europe/Bucharest, independent de TZ runtime.
    timeZone: "Europe/Bucharest",
    liveMaxAgeMs: 120000,
    bmsMaxAgeMs: 120000,
    dvccReadbackMaxAgeMs: 120000,
    dvccRetryMs: 15000,
    dvccMaxAttempts: 3,
    targetMinSoc: 20,
    targetMaxSoc: 100,
    targetDefaultMinutes: 360,
    targetMaxMinutes: 1440,
    pauseMaxMinutes: 1440,
    alertsDefault: true,
    reportDefault: false,
    reportDefaultTime: "20:00",
    reportWindowMinutes: 15,
    alertDebounceMs: 15000,
    alertCooldownMs: 120000,
    alertCclDeltaA: 10,
    haDailyMaxAgeMs: 30 * 60 * 1000,
    // Optional: EXCLUSIV senzori de energie pentru ziua curenta, nu contoare cumulative.
    entityDailyPvSources: [
        "sensor.primo_5_0_1_energy_day",
        "sensor.inverter_daily_yield",
        "sensor.inverter_daily_yield_2"
    ],
    energyCumulativeEntities: {
        import: "sensor.shelly_pro_3em_id_40_consumption",
        export: "sensor.shelly_pro_3em_id_40_feed_in",
        charge: "sensor.gx_device_dc_battery_charge_energy",
        discharge: "sensor.gx_device_dc_battery_discharge_energy"
    },
    energyStateBase: "/data/solar-forecast/daily-energy-v1",
    energySaveEveryMs: 300000,
    energyBoundaryMaxGapMs: 5 * 60000,
    entityDailyPv: "", // legacy, not used by the new energy collector
    entityDailyGridImport: "",
    entityDailyGridExport: "",
    entityDailyBatteryCharge: "",
    entityDailyBatteryDischarge: "",
    forceDefaultA: 100,
    forceMaxA: 100,
    forceMinMinutes: 1,
    forceMaxMinutes: 60
};

cfg.haToken = env.get("SOLAR_HA_TOKEN") || cfg.haToken;
cfg.telegramBotToken = env.get("SOLAR_TELEGRAM_TOKEN") || cfg.telegramBotToken;
cfg.telegramChatId = env.get("SOLAR_TELEGRAM_CHAT_ID") || cfg.telegramChatId;
flow.set("solar_cfg", cfg);
flow.set("discharge_request",null);flow.set("discharge_cancel",!!(flow.get("discharge_bridge")||{}).active);
flow.set("controller_enabled", cfg.enableOutputDefault);
flow.set("grid_guard", false);
flow.set("grid_guard_hits", 0);
flow.set("grid_release_hits", 0);
flow.set("charge_blocked", false);
flow.set("last_dvcc_sent", null);
flow.set("last_status_ts", 0);

// filtrele se reinitializeaza din valorile live la primul tick
flow.set("grid_total_filtered", null);
flow.set("grid_total_filtered_ts", 0);
flow.set("battery_voltage_filtered", null);
flow.set("battery_voltage_filtered_ts", 0);
flow.set("bms_max_cell_filtered", null);
flow.set("bms_max_cell_filtered_ts", 0);
flow.set("bms_temp_filtered", null);
flow.set("bms_temp_filtered_ts", 0);

node.status({fill:"blue",shape:"ring",text:`CONFIG v2.8.1 loaded - ${cfg.enableOutputDefault ? "CONTROL ON" : "DRY RUN"}`});
msg.payload=Date.now();

flow.set("telegram_session_start", Math.floor(Date.now()/1000));
flow.set("force_until",0);
flow.set("force_current_a",0);
flow.set("controller_status",null);
flow.set("manual_target",null);
flow.set("pause_until",0);
flow.set("writer_state",{});
flow.set("writer_fault",null);
flow.set("telegram_inflight",null);
flow.set("telegram_start",Date.now());
flow.set("telegram_alert_state",null);
flow.set("report_last_check",null);
flow.set("controller_events",[]);
flow.set("daily_soc",null);
flow.set("controller_started",Date.now());
flow.set("readback_confirmed",false);
flow.set("source_faults",{});
const botId=String(cfg.telegramBotToken).split(":")[0];
if(flow.get("telegram_offset_bot")!==botId){flow.set("telegram_update_offset",0);flow.set("telegram_offset_bot",botId);}
if(typeof flow.get("alerts_enabled")!=="boolean")flow.set("alerts_enabled",cfg.alertsDefault);
if(typeof flow.get("report_enabled")!=="boolean")flow.set("report_enabled",cfg.reportDefault);
if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(flow.get("report_time")||""))flow.set("report_time",cfg.reportDefaultTime);
flow.set("energy_ready",false);
flow.set("daily_energy",null);
flow.set("energy_storage_status","LOADING");
return {filename:cfg.energyStateBase+".A.json"};

const cfg = flow.get("solar_cfg");
if (!cfg) {
    node.status({fill:"red", shape:"ring", text:"CONFIG missing"});
    return null;
}

if (!cfg.haUrl || cfg.haUrl.includes("HOME_ASSISTANT_IP") ||
    !cfg.haToken || cfg.haToken.includes("PASTE_LONG_LIVED_ACCESS_TOKEN")) {
    node.status({fill:"yellow", shape:"ring", text:"Configureaza HA URL + TOKEN"});
    return null;
}

msg.requestTimeout=10000;
msg.method = "GET";
msg.url = cfg.haUrl.replace(/\/$/, "") + "/api/states";
msg.headers = {
    "Authorization": "Bearer " + cfg.haToken,
    "Content-Type": "application/json"
};
return msg;

const cfg = flow.get("solar_cfg");
if (!cfg || !Array.isArray(msg.payload)) {
    for(const k of ["forecast_valid","forecast_tomorrow_data_valid","forecast_remaining_data_valid","forecast_power_data_valid"])flow.set(k,false);
    flow.set("ha_error","INVALID_RESPONSE");
    node.status({fill:"red", shape:"ring", text:"HA response invalid"});
    return null;
}

flow.set("ha_error",null);flow.set("ha_success_ts",Date.now());
function findEntity(exactId, fallbackWords) {
    let e = msg.payload.find(x => x && x.entity_id === exactId);
    if (e) return e;
    return undefined; // exact entity IDs only
}
function n(v) { if(v===null||v===undefined||typeof v==="boolean"||String(v).trim()==="")return null; const x = Number(v); return Number.isFinite(x)&&x>=0 ? x : null; }
function clamp(x, lo, hi) { return Math.max(lo, Math.min(hi, x)); }
function entityTs(e) {
    if (!e) return 0;
    const t = Date.parse(e.last_updated || e.last_changed || "");
    return Number.isFinite(t) ? t : 0;
}
function confidence3(p10, p50, p90) {
    if (p50 === null || p50 <= 0 || p10 === null) return null;
    const lower = clamp(p10 / p50, 0, 1);
    if (p90 === null || p90 <= 0) return lower;
    const upper = clamp(p50 / p90, 0, 1);
    return clamp((lower + upper) / 2, 0, 1);
}

const tomorrow = findEntity(cfg.entityTomorrow,["solcast","forecast","tomorrow"]);
const remaining = findEntity(cfg.entityRemainingToday,["solcast","forecast","remaining","today"]);
const powerNowEnt = findEntity(cfg.entityPowerNow,["solcast","power","now"]);
const power30Ent = findEntity(cfg.entityPower30m,["solcast","power","30"]);
const power1hEnt = findEntity(cfg.entityPower1h,["solcast","power","1","hour"]);

if (!tomorrow) {
    flow.set("forecast_valid", false);
    flow.set("forecast_tomorrow_data_valid", false);
    flow.set("forecast_remaining_data_valid", false);
    flow.set("forecast_power_data_valid", false);
    // legacy flags
    flow.set("forecast_tomorrow_valid", false);
    flow.set("forecast_remaining_valid", false);
    flow.set("forecast_power_valid", false);
    node.status({fill:"red", shape:"ring", text:"Solcast TOMORROW lipseste"});
    msg.payload={ok:false,reason:"Tomorrow entity not found",expected:cfg.entityTomorrow};
    return msg;
}

const p50Tomorrow=n(tomorrow.state);
const p10Tomorrow=n(tomorrow.attributes?.estimate10);
const p90Tomorrow=n(tomorrow.attributes?.estimate90);
const remainingP50=remaining?n(remaining.state):null;
const remainingP10=remaining?n(remaining.attributes?.estimate10):null;
const remainingP90=remaining?n(remaining.attributes?.estimate90):null;
const powerNow=powerNowEnt?n(powerNowEnt.state):null;
const power30=power30Ent?n(power30Ent.state):null;
const power1h=power1hEnt?n(power1hEnt.state):null;

if (p50Tomorrow === null || p50Tomorrow < 0) {
    flow.set("forecast_valid", false);
    flow.set("forecast_tomorrow_data_valid", false);
    flow.set("forecast_tomorrow_valid", false);
    node.status({fill:"red",shape:"ring",text:"Solcast P50 invalid"});
    msg.payload={ok:false,reason:"Tomorrow P50 invalid",entity:tomorrow.entity_id};
    return msg;
}

const conf=confidence3(p10Tomorrow,p50Tomorrow,p90Tomorrow);
const spreadKwh=(p10Tomorrow!==null&&p90Tomorrow!==null)?Math.max(0,p90Tomorrow-p10Tomorrow):null;
const spreadPct=(spreadKwh!==null&&p50Tomorrow>0)?spreadKwh/p50Tomorrow:null;

const tomorrowTs=entityTs(tomorrow);
const remainingTs=entityTs(remaining);
const powerTsCandidates=[powerNowEnt,power30Ent,power1hEnt].map(entityTs).filter(x=>x>0);
const powerTs=powerTsCandidates.length?Math.min(...powerTsCandidates):0;

const tomorrowDataValid=p50Tomorrow!==null;
const remainingDataValid=(remainingP10!==null&&remainingP10>=0)||(remainingP50!==null&&remainingP50>=0);
const powerDataValid=powerNow!==null||power30!==null||power1h!==null;

const nowTs=Date.now();
const tomorrowFresh=tomorrowDataValid&&tomorrowTs>0&&(nowTs-tomorrowTs)<=Number(cfg.tomorrowForecastMaxAgeMs||6*60*60*1000);
const remainingFresh=remainingDataValid&&remainingTs>0&&(nowTs-remainingTs)<=Number(cfg.remainingForecastMaxAgeMs||60*60*1000);
const powerFresh=powerDataValid&&powerTs>0&&(nowTs-powerTs)<=Number(cfg.powerForecastMaxAgeMs||60*60*1000);
const tomorrowAgeMin=tomorrowTs>0?Math.max(0,(nowTs-tomorrowTs)/60000):null;
const remainingAgeMin=remainingTs>0?Math.max(0,(nowTs-remainingTs)/60000):null;
const powerAgeMin=powerTs>0?Math.max(0,(nowTs-powerTs)/60000):null;

flow.set("forecast_tomorrow_p50",p50Tomorrow);
flow.set("forecast_tomorrow_p10",p10Tomorrow);
flow.set("forecast_tomorrow_p90",p90Tomorrow);
flow.set("forecast_remaining_p50",remainingP50);
flow.set("forecast_remaining_p10",remainingP10);
flow.set("forecast_remaining_p90",remainingP90);
flow.set("forecast_power_now",powerNow);
flow.set("forecast_power_30m",power30);
flow.set("forecast_power_1h",power1h);
flow.set("forecast_confidence",conf);
flow.set("forecast_spread_kwh",spreadKwh);
flow.set("forecast_spread_pct",spreadPct);

flow.set("forecast_tomorrow_ts",tomorrowDataValid?tomorrowTs:0);
flow.set("forecast_remaining_ts",remainingDataValid?remainingTs:0);
flow.set("forecast_power_ts",powerDataValid?powerTs:0);

// v2.7.1: DATA VALID este separat de FRESH.
flow.set("forecast_tomorrow_data_valid",tomorrowDataValid);
flow.set("forecast_remaining_data_valid",remainingDataValid);
flow.set("forecast_power_data_valid",powerDataValid);
flow.set("forecast_tomorrow_fresh",tomorrowFresh);
flow.set("forecast_remaining_fresh",remainingFresh);
flow.set("forecast_power_fresh",powerFresh);

// Legacy flags pastrate pentru compatibilitate cu eventuale noduri vechi.
flow.set("forecast_tomorrow_valid",tomorrowDataValid);
flow.set("forecast_remaining_valid",remainingDataValid);
flow.set("forecast_power_valid",powerDataValid);
flow.set("forecast_ts",tomorrowTs || Date.now());
flow.set("forecast_valid",tomorrowFresh);

node.status({
    fill:tomorrowFresh?"green":"yellow",shape:"dot",
    text:`P50 ${p50Tomorrow.toFixed(1)} | Tomorrow ${tomorrowFresh?"FRESH":"STALE"} ${tomorrowAgeMin===null?"?":Math.round(tomorrowAgeMin)}m`
});

msg.payload={
    ok:true,
    tomorrowP10_kWh:p10Tomorrow,tomorrowP50_kWh:p50Tomorrow,tomorrowP90_kWh:p90Tomorrow,
    confidence:conf,spread_kWh:spreadKwh,spread_pct_of_P50:spreadPct,
    remainingTodayP10_kWh:remainingP10,remainingTodayP50_kWh:remainingP50,remainingTodayP90_kWh:remainingP90,
    powerNow_W:powerNow,power30m_W:power30,power1h_W:power1h,
    tomorrowEntity:tomorrow.entity_id,remainingEntity:remaining?.entity_id||null,
    tomorrowLastUpdated:tomorrow.last_updated||null,
    remainingLastUpdated:remaining?.last_updated||null,
    tomorrowDataValid,remainingDataValid,powerDataValid,
    tomorrowFresh,remainingFresh,powerFresh,
    tomorrowAgeMin,remainingAgeMin,powerAgeMin,
    tomorrowMaxAgeMin:Number(cfg.tomorrowForecastMaxAgeMs||0)/60000,
    remainingMaxAgeMin:Number(cfg.remainingForecastMaxAgeMs||0)/60000,
    powerMaxAgeMin:Number(cfg.powerForecastMaxAgeMs||0)/60000
};
return msg;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=0&&v<=100;
flow.set("soc",valid?v:null);flow.set("soc_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=20&&v<=80;
flow.set("battery_voltage",valid?v:null);flow.set("battery_voltage_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=-1000&&v<=1000;
flow.set("battery_current",valid?v:null);flow.set("battery_current_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=-1000000&&v<=1000000;
flow.set("grid_l1",valid?v:null);flow.set("grid_l1_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=-1000000&&v<=1000000;
flow.set("grid_l2",valid?v:null);flow.set("grid_l2_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=-1000000&&v<=1000000;
flow.set("grid_l3",valid?v:null);flow.set("grid_l3_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=0&&v<=1;
flow.set("dc_overfeed",valid?v:null);flow.set("dc_overfeed_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=0&&v<=1;
flow.set("bms_connected",valid?v:null);flow.set("bms_connected_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=0&&v<=1000;
flow.set("bms_ccl",valid?v:null);flow.set("bms_ccl_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=20&&v<=80;
flow.set("bms_cvl",valid?v:null);flow.set("bms_cvl_ts",valid?Date.now():0);
return null;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=1&&v<=5;
flow.set("bms_max_cell",valid?v:null);flow.set("bms_max_cell_ts",valid?Date.now():0);
return msg;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=1&&v<=5;
flow.set("bms_min_cell",valid?v:null);flow.set("bms_min_cell_ts",valid?Date.now():0);
return msg;

const r=msg.payload;
const v=(r===null||r===undefined||typeof r==="boolean"||String(r).trim()==="")?NaN:Number(r);
const valid=Number.isFinite(v)&&v>=-60&&v<=120;
flow.set("bms_temp",valid?v:null);flow.set("bms_temp_ts",valid?Date.now():0);
return null;

const cfg=flow.get("solar_cfg");
if(!cfg){node.status({fill:"red",shape:"ring",text:"CONFIG missing"});return [null,null];}

function val(key){
    if(key.startsWith("bms_")){const ts=Number(flow.get(key+"_ts")||0);if(!ts||Date.now()-ts>cfg.bmsMaxAgeMs)return null;}const raw=flow.get(key);if(raw===null||raw===undefined||raw==="")return null;const x=Number(raw);return Number.isFinite(x)?x:null;}
function clamp(x,lo,hi){return Math.max(lo,Math.min(hi,x));}
function fresh(validKey,tsKey,maxAge){
    if(flow.get(validKey)!==true)return false;
    const ts=val(tsKey);return ts!==null&&ts>0&&(Date.now()-ts)<=maxAge;
}
function ema(key,sample,tauSec){
    if(sample===null||!Number.isFinite(sample))return val(key);
    const now=Date.now();
    const prev=val(key),prevTs=val(key+"_ts");
    if(prev===null||prevTs===null||prevTs<=0||now<=prevTs){
        flow.set(key,sample);flow.set(key+"_ts",now);return sample;
    }
    const dt=Math.max(0.001,(now-prevTs)/1000);
    const alpha=1-Math.exp(-dt/Math.max(0.1,tauSec));
    const out=prev+alpha*(sample-prev);
    flow.set(key,out);flow.set(key+"_ts",now);return out;
}

// Timed commands use absolute deadlines; no timer can silently enable DRY RUN.
function event(kind,detail){const q=flow.get("controller_events")||[];q.push({kind,detail,ts:Date.now()});flow.set("controller_events",q.slice(-40));}
const nowMs=Date.now();
const localParts=new Intl.DateTimeFormat("en-GB",{timeZone:cfg.timeZone,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",hourCycle:"h23"}).formatToParts(new Date(nowMs));
const localMap=Object.fromEntries(localParts.map(p=>[p.type,p.value]));
const localDay=localMap.year+"-"+localMap.month+"-"+localMap.day;
const localHour=Number(localMap.hour);
let mt=flow.get("manual_target");
if(mt&&mt.until<=nowMs){flow.set("manual_target",null);event("TARGET_EXPIRED","Tinta manuala a expirat; revenire la forecast.");}
const pu=Number(flow.get("pause_until")||0);
if(pu>0&&pu<=nowMs){flow.set("pause_until",0);flow.set("writer_state",{});event("PAUSE_EXPIRED","Pauza a expirat; controlul poate relua scrierile daca este activ local.");}
const fu=Number(flow.get("force_until")||0);
if(fu>0&&fu<=nowMs){flow.set("force_until",0);flow.set("force_current_a",0);event("FORCE_EXPIRED","FORCE a expirat; revenire la strategia automata/manuala.");}
// Measured SOC range only; never labelled a full-day history after partial observation.
const socSample=val("soc"),socTs=Number(flow.get("soc_ts")||0);
let ds=flow.get("daily_soc");
if(socSample!==null&&socTs>0&&nowMs-socTs<=cfg.liveMaxAgeMs){
 if(!ds||ds.day!==localDay)ds={day:localDay,start:nowMs,min:socSample,max:socSample,last:nowMs};
 else{ds.min=Math.min(ds.min,socSample);ds.max=Math.max(ds.max,socSample);ds.last=nowMs;}
 flow.set("daily_soc",ds);
}

// -------- LIVE VICTRON --------
const soc=val("soc"),battV=val("battery_voltage"),battI=val("battery_current");
const g1=val("grid_l1"),g2=val("grid_l2"),g3=val("grid_l3");
const overFeed=val("dc_overfeed");
if(soc===null||battV===null||battI===null||g1===null||g2===null||g3===null){
    const status={timestamp:Date.now(),enabled:flow.get("controller_enabled")===true,controllerFault:"LIVE_MISSING",soc,desiredA:0};
    flow.set("controller_status",status);node.status({fill:"red",shape:"ring",text:"Lipsa date: cerere 0A"});return [{payload:0},{payload:status}];
}
const gridTotalW=g1+g2+g3;                 // + import / - export
const netExportW=gridTotalW<0?-gridTotalW:0;
const netImportW=gridTotalW>0?gridTotalW:0;

// Grid Guard foloseste valoarea instantanee. Boost-ul foloseste filtrul lent.
const gridTotalFilteredW=ema("grid_total_filtered",gridTotalW,Number(cfg.gridFilterTauSec||25));
const netExportFilteredW=gridTotalFilteredW!==null&&gridTotalFilteredW<0?-gridTotalFilteredW:0;
const battVFiltered=ema("battery_voltage_filtered",battV,Number(cfg.batteryFilterTauSec||10));

// -------- BMS READ-ONLY --------
const bmsConnectedRaw=val("bms_connected");
const bmsCcl=val("bms_ccl");
const bmsCvl=val("bms_cvl");
const bmsMaxCell=val("bms_max_cell");
const bmsMinCell=val("bms_min_cell");
const bmsTemp=val("bms_temp");
const bmsAnyData=[bmsCcl,bmsCvl,bmsMaxCell,bmsMinCell,bmsTemp].some(x=>x!==null);
const bmsConnected=bmsConnectedRaw===1;
const bmsMaxCellFiltered=bmsMaxCell!==null?ema("bms_max_cell_filtered",bmsMaxCell,Number(cfg.batteryFilterTauSec||10)):val("bms_max_cell_filtered");
const bmsTempFiltered=bmsTemp!==null?ema("bms_temp_filtered",bmsTemp,Number(cfg.batteryFilterTauSec||10)):val("bms_temp_filtered");
const cellDeltaV=(bmsMaxCell!==null&&bmsMinCell!==null)?Math.max(0,bmsMaxCell-bmsMinCell):null;

// -------- SOLCAST: DATA VALID + FRESHNESS SEPARATE v2.7.1 --------
const tomorrowDataValid=flow.get("forecast_tomorrow_data_valid")===true;
const remainingDataValid=flow.get("forecast_remaining_data_valid")===true;
const powerDataValid=flow.get("forecast_power_data_valid")===true;

const tomorrowValid=fresh("forecast_tomorrow_data_valid","forecast_tomorrow_ts",Number(cfg.tomorrowForecastMaxAgeMs||6*60*60*1000));
const remainingValid=fresh("forecast_remaining_data_valid","forecast_remaining_ts",Number(cfg.remainingForecastMaxAgeMs||60*60*1000));
const powerValid=fresh("forecast_power_data_valid","forecast_power_ts",Number(cfg.powerForecastMaxAgeMs||60*60*1000));
const forecastValid=tomorrowValid; // compatibilitate status/Telegram

const p50=tomorrowValid?val("forecast_tomorrow_p50"):null;
const p10=tomorrowValid?val("forecast_tomorrow_p10"):null;
const p90=tomorrowValid?val("forecast_tomorrow_p90"):null;
const remainingP50=remainingValid?val("forecast_remaining_p50"):null;
const remainingP10=remainingValid?val("forecast_remaining_p10"):null;
const remainingP90=remainingValid?val("forecast_remaining_p90"):null;
const powerNow=powerValid?val("forecast_power_now"):null;
const power30=powerValid?val("forecast_power_30m"):null;
const power1h=powerValid?val("forecast_power_1h"):null;
let confidence=tomorrowValid?val("forecast_confidence"):null;
if(confidence===null&&p10!==null&&p50!==null&&p50>0)confidence=clamp(p10/p50,0,1);
const spreadKwh=tomorrowValid?val("forecast_spread_kwh"):null;
const spreadPct=tomorrowValid?val("forecast_spread_pct"):null;

const tomorrowTs=val("forecast_tomorrow_ts");
const remainingTs=val("forecast_remaining_ts");
const powerTs=val("forecast_power_ts");
const tomorrowAgeMin=tomorrowTs?Math.max(0,(Date.now()-tomorrowTs)/60000):null;
const remainingAgeMin=remainingTs?Math.max(0,(Date.now()-remainingTs)/60000):null;
const powerAgeMin=powerTs?Math.max(0,(Date.now()-powerTs)/60000):null;

// -------- TARGET PLANNER v2.6, cu freshness fix v2.7.1 --------
let forecastClass="FALLBACK";
let baseTargetSoc=cfg.normalTargetSoc;
let finalTargetSoc=cfg.normalTargetSoc;
let targetSoc=cfg.normalTargetSoc;
let veryPoorStage="NONE";
let veryPoorRaiseReason="NONE";
let energyNeededTo100Kwh=null;
let marginTo100=null;

if(tomorrowValid&&p50!==null){
    if(p50<cfg.veryPoorTomorrowKwh){forecastClass="VERY_POOR";baseTargetSoc=cfg.veryPoorHoldSoc;finalTargetSoc=cfg.veryPoorFinalSoc;targetSoc=baseTargetSoc;}
    else if(p50<cfg.poorTomorrowKwh){forecastClass="POOR";baseTargetSoc=95;finalTargetSoc=95;targetSoc=95;}
    else if(p50<cfg.mediumTomorrowKwh){forecastClass="MEDIUM";baseTargetSoc=90;finalTargetSoc=90;targetSoc=90;}
    else{forecastClass="GOOD";baseTargetSoc=cfg.normalTargetSoc;finalTargetSoc=cfg.normalTargetSoc;targetSoc=cfg.normalTargetSoc;}

    if(forecastClass!=="VERY_POOR"&&confidence!==null&&confidence<cfg.lowConfidence&&targetSoc<100){
        targetSoc=Math.min(100,targetSoc+5);baseTargetSoc=targetSoc;finalTargetSoc=targetSoc;forecastClass+="_UNCERTAIN";
    }
}

let conservativeSolarRemainingKwh=null;
let conservativeSolarSource="NONE";
if(remainingValid&&remainingP10!==null&&remainingP10>=0){conservativeSolarRemainingKwh=remainingP10;conservativeSolarSource="P10";}
else if(remainingValid&&remainingP50!==null&&remainingP50>=0){conservativeSolarRemainingKwh=remainingP50*cfg.p50ToConservativeFactor;conservativeSolarSource="P50xFACTOR";}
const usableSolarForBatteryKwh=conservativeSolarRemainingKwh!==null?conservativeSolarRemainingKwh*cfg.pvUsableFractionForBattery:null;

if(forecastClass==="VERY_POOR"){
    energyNeededTo100Kwh=Math.max(0,cfg.batteryCapacityKwh*Math.max(0,100-soc)/100/cfg.chargeEfficiency);
    marginTo100=(usableSolarForBatteryKwh!==null&&energyNeededTo100Kwh>0.05)?usableSolarForBatteryKwh/energyNeededTo100Kwh:null;
    const now=new Date();
    const afterNominal=localHour>=Number(cfg.veryPoorNominalRaiseHour||14);
    const earlyEnergyTrigger=marginTo100!==null&&marginTo100<=Number(cfg.veryPoorEarlyTriggerMargin||1.25);

    if(soc>=99.5){targetSoc=100;veryPoorStage="FINAL_100";veryPoorRaiseReason="ALREADY_FULL";}
    else if(!remainingValid){
        // Maine este VERY_POOR dar nu mai avem un Remaining Today proaspat: nu riscam sa amanam.
        targetSoc=100;veryPoorStage="FINAL_100";veryPoorRaiseReason="REMAINING_FORECAST_STALE";
    }
    else if(afterNominal){targetSoc=100;veryPoorStage="FINAL_100";veryPoorRaiseReason="NOMINAL_TIME";}
    else if(earlyEnergyTrigger){targetSoc=100;veryPoorStage="FINAL_100";veryPoorRaiseReason="EARLY_ENERGY_RISK";}
    else{targetSoc=cfg.veryPoorHoldSoc;veryPoorStage="HOLD_90";veryPoorRaiseReason="DELAY_TO_PROTECT_FULL_TIME";}
}

// v2.8 manual target: bounded lifetime, still under taper/BMS/NET Guard.
const forecastTargetSoc=targetSoc;
const manual=flow.get("manual_target");
const manualActive=!!manual&&manual.until>Date.now();
if(manualActive){targetSoc=manual.soc;finalTargetSoc=manual.soc;}
// -------- HYSTERESIS --------
let blocked=flow.get("charge_blocked")===true;
const oldTarget=val("target_soc");
if(soc>=targetSoc)blocked=true;
if(blocked&&soc<=targetSoc-cfg.socHysteresis)blocked=false;
if(blocked&&oldTarget!==null&&targetSoc>oldTarget&&soc<targetSoc-0.5)blocked=false;
flow.set("charge_blocked",blocked);flow.set("target_soc",targetSoc);

// -------- SOLAR OPPORTUNITY --------
const upcomingPower=Math.max(powerNow??0,power30??0,power1h??0);
const solarOpportunity=(remainingP50!==null&&remainingP50>=cfg.fastRemainingTodayKwh)||(powerNow!==null&&powerNow>=cfg.fastPowerNowW)||(upcomingPower>=cfg.fastPowerUpcomingW)||(netExportFilteredW>=cfg.fastNetExportW);

// -------- CURRENT POLICY: 50A NORMAL, BOOST LOW-SOC --------
const socGapPct=Math.max(0,targetSoc-soc);
const batteryEnergyNeededKwh=socGapPct>0?(cfg.batteryCapacityKwh*socGapPct/100/cfg.chargeEfficiency):0;
const energyMargin=(usableSolarForBatteryKwh!==null&&batteryEnergyNeededKwh>0.05)?usableSolarForBatteryKwh/batteryEnergyNeededKwh:null;

let strategyA=0;
let energyDecision="BLOCKED_AT_TARGET";
let boostReason="NONE";
if(!blocked){
    strategyA=Number(cfg.normalChargeMaxA||50);
    energyDecision="NORMAL_MAX_50A";

    const need70=(energyMargin!==null&&energyMargin<Number(cfg.boost70EnergyMargin||1.40))||netExportFilteredW>=Number(cfg.boost70NetExportW||2500);
    if(soc<Number(cfg.lowSocThreshold||50)&&solarOpportunity&&need70){
        strategyA=Math.max(strategyA,Number(cfg.lowSocBoostA||70));
        boostReason=netExportFilteredW>=Number(cfg.boost70NetExportW||2500)?"FILTERED_NET_EXPORT":"LOW_ENERGY_MARGIN";
        energyDecision="LOW_SOC_BOOST_70A";
    }

    const need100=(energyMargin!==null&&energyMargin<Number(cfg.boost100EnergyMargin||1.10))||netExportFilteredW>=Number(cfg.boost100NetExportW||4000);
    if(soc<Number(cfg.veryLowSocThreshold||30)&&solarOpportunity&&need100){
        strategyA=Math.max(strategyA,Number(cfg.veryLowSocBoostA||100));
        boostReason=netExportFilteredW>=Number(cfg.boost100NetExportW||4000)?"FILTERED_NET_EXPORT":"CRITICAL_ENERGY_MARGIN";
        energyDecision="VERY_LOW_SOC_BOOST_100A";
    }
}
strategyA=clamp(Math.round(strategyA),0,cfg.hardMaxA);
const automaticStrategyA=strategyA;

// -------- TELEGRAM FORCE: forecast/target ignorate, protectiile raman --------
const forceUntil=Number(flow.get("force_until")||0);
const forceRequestedA=Number(flow.get("force_current_a")||cfg.forceDefaultA||cfg.hardMaxA);
const forceActive=forceUntil>Date.now();
let forceMinutesLeft=0;
if(forceActive){
    forceMinutesLeft=Math.ceil((forceUntil-Date.now())/60000);
    strategyA=clamp(Math.round(forceRequestedA),1,Math.min(Number(cfg.forceMaxA||cfg.hardMaxA),cfg.hardMaxA));
    energyDecision="TELEGRAM_FORCE_"+strategyA+"A";
}else if(forceUntil>0){flow.set("force_until",0);flow.set("force_current_a",0);}

// -------- BATTERY-AWARE CAP v2.7 --------
// Acesta este un plafon proactiv; nu inlocuieste BMS/DVCC.
let batteryAwareCapA=cfg.hardMaxA;
let batteryTaperReason="NONE";
let batteryTaperSource="NONE";
let cellCeilingV=null,cellHeadroomV=null,packCeilingV=null,packHeadroomV=null;
let bmsCclLimited=false;

if(cfg.batteryAwareEnabled!==false){
    const cellCount=Math.max(1,Number(cfg.batteryCellCount||16));

    // 1) CCL BMS: respectam direct orice reducere transmisa de BMS.
    if(bmsConnected&&bmsCcl!==null&&bmsCcl>=0){
        const cclCap=clamp(Math.floor(bmsCcl),0,cfg.hardMaxA);
        if(cclCap<batteryAwareCapA){batteryAwareCapA=cclCap;batteryTaperReason="BMS_CCL";batteryTaperSource="CCL";}
        bmsCclLimited=cclCap<strategyA;
    }

    // 2) Max cell + CVL este sursa preferata pentru taper langa full.
    if(bmsConnected&&bmsCvl!==null&&bmsCvl>0&&bmsMaxCellFiltered!==null&&bmsMaxCellFiltered>0){
        cellCeilingV=Math.min(bmsCvl/cellCount,Number(cfg.cellSoftCeilingV||99));
        cellHeadroomV=cellCeilingV-bmsMaxCellFiltered;
        let cellCap=cfg.hardMaxA;
        if(cellHeadroomV<=Number(cfg.cellTaper10HeadroomV||0.010))cellCap=10;
        else if(cellHeadroomV<=Number(cfg.cellTaper20HeadroomV||0.020))cellCap=20;
        else if(cellHeadroomV<=Number(cfg.cellTaper30HeadroomV||0.035))cellCap=30;
        else if(cellHeadroomV<=Number(cfg.cellTaper40HeadroomV||0.050))cellCap=40;
        if(cellCap<batteryAwareCapA){batteryAwareCapA=cellCap;batteryTaperReason="MAX_CELL_HEADROOM";batteryTaperSource="CELL";}
    }
    // 3) Daca max-cell lipseste, folosim pack voltage vs CVL ca fallback BMS-aware.
    else if(bmsConnected&&bmsCvl!==null&&bmsCvl>0&&battVFiltered!==null){
        packCeilingV=Math.min(bmsCvl,Number(cfg.cellSoftCeilingV||99)*cellCount);
        packHeadroomV=packCeilingV-battVFiltered;
        let packCap=cfg.hardMaxA;
        if(packHeadroomV<=Number(cfg.cellTaper10HeadroomV||0.010)*cellCount)packCap=10;
        else if(packHeadroomV<=Number(cfg.cellTaper20HeadroomV||0.020)*cellCount)packCap=20;
        else if(packHeadroomV<=Number(cfg.cellTaper30HeadroomV||0.035)*cellCount)packCap=30;
        else if(packHeadroomV<=Number(cfg.cellTaper40HeadroomV||0.050)*cellCount)packCap=40;
        if(packCap<batteryAwareCapA){batteryAwareCapA=packCap;batteryTaperReason="PACK_CVL_HEADROOM";batteryTaperSource="PACK";}
    }
    // 4) Fara CVL/cell telemetry: SOC ramane doar fallback foarte aproape de 100%.
    else{
        let socCap=cfg.hardMaxA;
        if(soc>=Number(cfg.fallbackSocTaper10||99))socCap=10;
        else if(soc>=Number(cfg.fallbackSocTaper20||97))socCap=20;
        else if(soc>=Number(cfg.fallbackSocTaper30||95))socCap=30;
        if(socCap<batteryAwareCapA){batteryAwareCapA=socCap;batteryTaperReason="SOC_FALLBACK";batteryTaperSource="SOC";}
    }

    // Temperatura este optionala; implicit OFF ca sa nu schimbam agresiv comportamentul PACE.
    if(cfg.temperatureSoftTaperEnabled===true&&bmsTempFiltered!==null){
        if(bmsTempFiltered<=Number(cfg.tempSoft30BelowC||5)||bmsTempFiltered>=Number(cfg.tempSoft30AboveC||45)){
            if(30<batteryAwareCapA){batteryAwareCapA=30;batteryTaperReason="TEMPERATURE_SOFT_CAP";batteryTaperSource="TEMP";}
        }
    }
}

batteryAwareCapA=clamp(Math.round(batteryAwareCapA),0,cfg.hardMaxA);
let desiredA=Math.min(strategyA,batteryAwareCapA);

// -------- NET 3-PHASE GRID GUARD: NEsCHIMBAT, INSTANTANEU --------
let guard=flow.get("grid_guard")===true;
let trip=Number(flow.get("grid_guard_hits")||0);
let release=Number(flow.get("grid_release_hits")||0);
const looksLikeGridCharging=gridTotalW>cfg.gridImportTripW&&battI>cfg.batteryChargingGuardA;
if(!guard){
    trip=looksLikeGridCharging?trip+1:0;
    if(trip>=cfg.guardTripSamples){guard=true;release=0;}
}else{
    const safeAgain=gridTotalW<=cfg.gridImportReleaseW||battI<=0;
    release=safeAgain?release+1:0;
    if(release>=cfg.guardReleaseSamples){guard=false;trip=0;release=0;}
}
flow.set("grid_guard",guard);flow.set("grid_guard_hits",trip);flow.set("grid_release_hits",release);

let guardCalculatedA=null,gridEquivalentA=null;
if(guard){
    if(gridTotalW>=cfg.guardHardStopImportW&&battI>cfg.batteryChargingGuardA){desiredA=0;guardCalculatedA=0;}
    else if(gridTotalW>0&&battI>0&&battV>0){
        gridEquivalentA=gridTotalW/battV;
        guardCalculatedA=Math.max(0,Math.floor(battI-gridEquivalentA-cfg.guardSafetyMarginA));
        desiredA=Math.min(desiredA,guardCalculatedA);
    }
}
// FORCE100 is a solar-only target, not a current override.
let solarOnlyCapA=null;
if(manualActive&&manual.solarOnly){
    solarOnlyCapA=Math.max(0,Math.floor(battI-gridTotalW/(Math.max(1,battV)*cfg.chargeEfficiency)-cfg.guardSafetyMarginA));
    desiredA=Math.min(desiredA,solarOnlyCapA);
}
desiredA=clamp(Math.round(desiredA),0,cfg.hardMaxA);

// v2.8 all decisions go through one verification gate; only it feeds the existing DVCC writer.
const enabled=flow.get("controller_enabled")===true;
const paused=Number(flow.get("pause_until")||0)>Date.now();
const mustSend=false; // writes are decided by the downstream gate, including readback/retries.
let out={payload:desiredA};

// -------- STATUS --------
const status={
    timestamp:Date.now(),paused,pauseUntil:Number(flow.get("pause_until")||0),
    manualTargetActive:manualActive,manualTarget:manualActive?manual:null,forecastTargetSoc,solarOnlyCapA,
    targetSource:manualActive?(manual.solarOnly?"FORCE100":"MANUAL"):"FORECAST",
    enabled,soc,targetSoc,baseTargetSoc,finalTargetSoc,blocked,
    desiredA,strategyA,automaticStrategyA,batteryAwareCapA,batteryTaperReason,batteryTaperSource,
    bmsConnected,bmsCcl,bmsCvl,bmsMaxCell,bmsMinCell,bmsMaxCellFiltered,bmsTemp,bmsTempFiltered,cellDeltaV,
    cellCeilingV,cellHeadroomV,packCeilingV,packHeadroomV,bmsCclLimited,
    veryPoorStage,veryPoorRaiseReason,veryPoorNominalRaiseHour:cfg.veryPoorNominalRaiseHour,
    energyNeededTo100Kwh,marginTo100,boostReason,
    forceActive,forceMinutesLeft,forceRequestedA:forceActive?strategyA:0,forceUntil:forceActive?forceUntil:0,
    batteryCapacityKwh:cfg.batteryCapacityKwh,batteryEnergyNeededKwh,
    remainingTodayP10:remainingP10,remainingTodayP50:remainingP50,remainingTodayP90:remainingP90,
    conservativeSolarRemainingKwh,conservativeSolarSource,usableSolarForBatteryKwh,energyMargin,energyDecision,
    batteryV:battV,batteryVFiltered:battVFiltered,batteryI:battI,
    gridL1W:g1,gridL2W:g2,gridL3W:g3,gridTotalW,gridTotalFilteredW,netExportW,netExportFilteredW,netImportW,
    gridGuard:guard,gridEquivalentA,gridGuardCalculatedA:guardCalculatedA,gridGuardTripSamples:trip,gridGuardReleaseSamples:release,
    forecastValid,
    tomorrowForecastDataValid:tomorrowDataValid,remainingForecastDataValid:remainingDataValid,powerForecastDataValid:powerDataValid,
    tomorrowForecastValid:tomorrowValid,remainingForecastValid:remainingValid,powerForecastValid:powerValid,
    tomorrowForecastAgeMin:tomorrowAgeMin,remainingForecastAgeMin:remainingAgeMin,powerForecastAgeMin:powerAgeMin,
    tomorrowForecastMaxAgeMin:Number(cfg.tomorrowForecastMaxAgeMs||0)/60000,
    remainingForecastMaxAgeMin:Number(cfg.remainingForecastMaxAgeMs||0)/60000,
    powerForecastMaxAgeMin:Number(cfg.powerForecastMaxAgeMs||0)/60000,
    forecastClass,tomorrowP10:p10,tomorrowP50:p50,tomorrowP90:p90,
    confidence,forecastSpreadKwh:spreadKwh,forecastSpreadPctOfP50:spreadPct,
    powerNowW:powerNow,power30mW:power30,power1hW:power1h,upcomingPowerW:upcomingPower,solarOpportunity,
    dcFeedInEnabled:overFeed===1,
    note:overFeed===1?"DC feed-in activ: limita DVCC poate sa nu limiteze complet MPPT-ul DC. Monitorizeaza separat.":""
};
status.plan={soc,targetSoc,forecastTargetSoc,finalTargetSoc,forecastClass,veryPoorStage,veryPoorRaiseReason,
    energyNeededToTargetKwh:batteryEnergyNeededKwh,
    energyNeededTo100Kwh:Math.max(0,cfg.batteryCapacityKwh*(100-soc)/100/cfg.chargeEfficiency),
    conservativeSolarRemainingKwh,usableSolarForBatteryKwh,energyMargin,marginTo100,
    nominalRaiseHour:cfg.veryPoorNominalRaiseHour,latestSafeStart:null};
flow.set("controller_status",status);

let fill=guard?"red":blocked?"yellow":enabled?"green":"grey";
let shape=enabled?"dot":"ring";
const marginTxt=energyMargin===null?"-":energyMargin.toFixed(1)+"x";
let txt=`${enabled?"ON":"DRY"} | SOC ${soc.toFixed(1)}→${targetSoc}% | ${desiredA}A | ${batteryTaperSource} | Grid ${Math.round(gridTotalW)}W`;
if(forceActive)txt=`FORCE ${forceMinutesLeft}m | req ${strategyA}A→${desiredA}A | SOC ${soc.toFixed(1)}% | Grid ${Math.round(gridTotalW)}W`;
if(guard)txt=`NET GRID GUARD | ${desiredA}A | GridNET ${Math.round(gridTotalW)}W`;
else if(batteryAwareCapA<strategyA)txt=`BATTERY CAP ${batteryTaperSource} | ${strategyA}A→${desiredA}A | SOC ${soc.toFixed(1)}%`;
node.status({fill,shape,text:txt});

const lastStatus=Number(flow.get("last_status_ts")||0);
let dbg=null;
if((enabled&&mustSend)||Date.now()-lastStatus>=cfg.statusEveryMs){dbg={payload:status};flow.set("last_status_ts",Date.now());}
return [out,dbg];

const cfg=flow.get("solar_cfg");if(!cfg)return null;
const enabled=msg.payload===true;
flow.set("controller_enabled",enabled);flow.set("writer_state",{});flow.set("pause_until",0);
if(!enabled){flow.set("force_until",0);flow.set("manual_target",null);}
node.status({fill:enabled?"green":"grey",shape:"dot",text:enabled?"CONTROL ON":"DRY RUN: limita DVCC existenta ramane"});
return {payload:Date.now()};

flow.set("grid_guard", false);
flow.set("grid_guard_hits", 0);
flow.set("grid_release_hits", 0);
flow.set("charge_blocked", false);
flow.set("last_dvcc_sent", null);
flow.set("last_status_ts", 0);
flow.set("grid_total_filtered", null);
flow.set("grid_total_filtered_ts", 0);
flow.set("battery_voltage_filtered", null);
flow.set("battery_voltage_filtered_ts", 0);
flow.set("bms_max_cell_filtered", null);
flow.set("bms_max_cell_filtered_ts", 0);
flow.set("bms_temp_filtered", null);
flow.set("bms_temp_filtered_ts", 0);
node.status({fill:"blue", shape:"ring", text:"Controller v2.7.1 state reset"});
flow.set("writer_fault",null);flow.set("writer_state",{});flow.set("manual_target",null);flow.set("force_until",0);flow.set("pause_until",0);return {payload:Date.now()};

const cfg=flow.get("solar_cfg");if(!cfg||cfg.telegramEnabled!==true)return null;
const token=String(cfg.telegramBotToken||"").trim();
if(!token||token.includes("PASTE_")){node.status({fill:"yellow",shape:"ring",text:"Configureaza token Telegram"});return null;}
const now=Date.now(),busy=flow.get("telegram_inflight");
if(now<Number(flow.get("telegram_poll_backoff")||0))return null;
if(busy&&now-busy.ts<12000)return null;
const id=String(now)+"-"+String(Math.random());flow.set("telegram_inflight",{id,ts:now});
const offset=Number(flow.get("telegram_update_offset")||0);
return {url:"https://api.telegram.org/bot"+token+"/getUpdates?timeout=0&limit=100&allowed_updates=%5B%22message%22%5D"+(offset>0?"&offset="+offset:""),requestTimeout:8000,telegram_poll_id:id};

const cfg=flow.get("solar_cfg");if(!cfg||cfg.telegramEnabled!==true)return null;
