 if(!s||s.schema!==1||s.timeZone!==cfg.timeZone||!Number.isSafeInteger(s.seq)||s.seq<0||!s.meters||typeof s.meters!=='object'||Array.isArray(s.meters)||!Number.isFinite(s.savedAt)||s.savedAt>Date.now()+60000)return false;
 for(const m of Object.values(s.meters)){
  if(!m||typeof m.entity!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(m.day)||typeof m.partial!=='boolean'||typeof m.estimated!=='boolean')return false;
  for(const k of ['total','last','lastTs','start','resets'])if(!Number.isFinite(m[k])||m[k]<0)return false;
 }
 return true;
}
const candidates=[];
for(const raw of [msg.energy_checkpoint_a,msg.payload]){
 try{const s=typeof raw==='string'?JSON.parse(raw):null;if(valid(s))candidates.push(s);}catch(e){}
}
const loaded=candidates.sort((a,b)=>b.seq-a.seq)[0];
flow.set("energy_state",loaded||{schema:1,timeZone:cfg.timeZone,seq:0,savedAt:Date.now(),meters:{}});
flow.set("energy_ready",true);flow.set("energy_save_requested",0);
flow.set("energy_storage_status",loaded?'RESTORED':'NEW_BASELINE');
node.status({fill:loaded?'green':'yellow',shape:'ring',text:loaded?'Contoare restaurate':'Prima baza: totaluri partiale'});
return {payload:Date.now()};

const cfg=flow.get("solar_cfg");if(!cfg||flow.get("energy_ready")!==true)return null;
if(!Array.isArray(msg.payload)||Number(msg.statusCode||200)!==200){flow.set("daily_energy",null);return null;}
const now=Date.now();
function day(ts){const p=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{timeZone:cfg.timeZone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(ts)).map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}`;}
const today=day(now);
function midnight(){let lo=now-30*3600000,hi=now;while(hi-lo>1){const m=Math.floor((lo+hi)/2);if(day(m)===today)hi=m;else lo=m;}return hi;}
function read(id){
 const e=msg.payload.find(x=>x?.entity_id===id);if(!e||e.state===null||e.state===undefined||typeof e.state==="boolean"||String(e.state).trim()==="")return null;
 const v=Number(e.state),u=String(e.attributes?.unit_of_measurement||"").trim().toLowerCase();
 if(!Number.isFinite(v)||v<0||!['kwh','wh'].includes(u))return null;
 return {value:u==='wh'?v/1000:v,updated:Date.parse(e.last_updated||"")};
}
let state=flow.get("energy_state")||{schema:1,timeZone:cfg.timeZone,seq:0,meters:{}};
const daily={day:today,fetchedAt:now,values:{},pvSources:[]};
const pvIds=[...new Set(cfg.entityDailyPvSources||[])];let pvTotal=0,pvComplete=pvIds.length>0;
for(const id of pvIds){
 const r=read(id);
 // A daily PV sensor still carrying yesterday's value must not count as today's production.
 const valid=r!==null&&Number.isFinite(r.updated)&&day(r.updated)===today;
 daily.pvSources.push({entity:id,kwh:valid?r.value:null});
 if(valid)pvTotal+=r.value;else pvComplete=false;
}
daily.values.pv={kwh:pvComplete?pvTotal:null,kind:'daily',partial:!pvComplete};
for(const [key,id] of Object.entries(cfg.energyCumulativeEntities||{})){
 const r=read(id);let m=state.meters[key];
 if(!r){daily.values[key]={kwh:null,entity:id,unavailable:true};continue;}
 if(!m||m.entity!==id){
  m={entity:id,day:today,total:0,last:r.value,lastTs:now,start:now,partial:true,estimated:false,resets:0};
 }else if(now<m.lastTs){
  m={entity:id,day:today,total:0,last:r.value,lastTs:now,start:now,partial:true,estimated:false,resets:0};
 }else if(m.day!==today){
  const boundary=midnight(),delta=r.value-m.last,span=now-m.lastTs;
  const nearby=span>0&&span<=cfg.energyBoundaryMaxGapMs&&day(m.lastTs)===day(boundary-1)&&delta>=0;
  // No exact midnight sample: apportion only a small crossing interval; explicitly mark estimate.
  m={entity:id,day:today,total:nearby?delta*(now-boundary)/span:0,last:r.value,lastTs:now,
   start:nearby?boundary:now,partial:!nearby,estimated:nearby&&delta>0&&now!==boundary,resets:delta<0?1:0};
 }else{
  const delta=r.value-m.last;
  if(delta>=0){m.total+=delta;}
  else{
   // Reset/replacement/correction: keep accumulated known energy and establish new baseline.
   // Do not add entire new counter value; post-reset origin is unknown.
   m.partial=true;m.resets+=1;
  }
  m.last=r.value;m.lastTs=now;
 }
 state.meters[key]=m;
 daily.values[key]={kwh:m.total,entity:id,kind:'cumulative-delta',partial:m.partial,estimated:m.estimated,start:m.start,resets:m.resets};
}
state.schema=1;state.timeZone=cfg.timeZone;state.savedAt=now;
flow.set("energy_state",state);flow.set("daily_energy",daily);
node.status({fill:'green',shape:'dot',text:`Energie ${today} | PV ${pvComplete?pvTotal.toFixed(2):'N/A'} kWh`});
// Two alternating snapshots: a torn write does not destroy the previous checkpoint.
if(now-Number(flow.get("energy_save_requested")||0)<cfg.energySaveEveryMs)return null;
state.seq=Number(state.seq||0)+1;flow.set("energy_state",state);flow.set("energy_save_requested",now);
return {filename:cfg.energyStateBase+'.'+(state.seq%2===0?'A':'B')+'.json',payload:JSON.stringify(state),energy_seq:state.seq};

// v2.8.2: independent charge ceiling, always applied before the sole DVCC gate.
const cfg=flow.get('solar_cfg');if(!cfg)return null;
const now=Date.now(),faults=flow.get('source_faults')||{};
function sample(k){const r=flow.get(k),ts=Number(flow.get(k+'_ts'));const age=now-ts;
 if(r===null||r===undefined||r===''||typeof r==='boolean'||!Number.isFinite(Number(r))||!Number.isFinite(ts)||ts<=0||age<0||age>20000||faults[k])return null;
 return Number(r);
}
const soc=sample('soc'),max=sample('bms_max_cell'),min=sample('bms_min_cell');
const delta=max!==null&&min!==null?max-min:null;
const valid=soc!==null&&soc>=0&&soc<=100&&max!==null&&min!==null&&min>=2&&max<=4&&max>=min;
let cap=Number(cfg.hardMaxA),reason='NONE',socCap=null,cellCap=null;
function limit(a,r){if(a<cap){cap=a;reason=r;}}
// Optional global commissioning cap is opt-in; never enabled by a missing setting.
if(cfg.commissioningChargeCapEnabled===true)limit(10,'COMMISSIONING_10A');
let st=flow.get('cell_guard_state')||{blocked:false,safeSince:0,started:now};
const previous=st.blocked;
if(!valid){cap=0;reason='CELL_TELEMETRY_INVALID';st.safeSince=0;}
else{
 // SOC taper is always active, including FORCE and when cell telemetry is present.
 if(soc>=90){socCap=Math.max(2,Math.floor(10-(Math.min(soc,98)-90)));limit(socCap,'SOC_TOP_TAPER');}
 cellCap=max>=3.45?2:max>=3.43?5:max>=3.40?10:cfg.hardMaxA;
 limit(cellCap,'RAW_MAX_CELL_TAPER');
 if(max>=3.40&&delta>=0.05)limit(2,'CELL_DELTA_TAPER');
 // No EMA/debounce on trip. A software stop is deliberately below BMS alarm thresholds.
 if(max>=3.50||(max>=3.40&&delta>=0.10)){
  st.blocked=true;st.safeSince=0;st.tripReason=max>=3.50?'CELL_HIGH_STOP':'CELL_DELTA_STOP';
 }
 if(st.blocked){
  if(max<=3.43&&delta<=0.05){
   if(!st.safeSince)st.safeSince=now;
   if(now-st.safeSince>=60000){st.blocked=false;st.safeSince=0;}
  }else st.safeSince=0;
 }
 if(st.blocked){cap=0;reason=st.tripReason||'CELL_STOP_HOLD';}
}
flow.set('cell_guard_state',st);
const g={timestamp:now,capA:cap,reason,blocked:st.blocked,valid,maxV:max,minV:min,deltaV:delta,socCapA:socCap,cellCapA:cellCap,releaseAfterSec:st.safeSince?Math.max(0,Math.ceil((60000-now+st.safeSince)/1000)):null};
flow.set('charge_guard',g);
if(previous!==st.blocked){
 const q=flow.get('controller_events')||[];
 q.push({kind:st.blocked?'CELL_STOP':'CELL_RECOVERED',ts:now,detail:st.blocked?`Incarcare oprita preventiv: ${reason}; max ${max} V, delta ${delta===null?'N/A':Math.round(delta*1000)} mV.`:'Protectie celule: conditii de reluare stabile 60 s; reincarcare permisa cu plafon redus.'});
 flow.set('controller_events',q.slice(-40));
}
if(flow.get('discharge_request')||flow.get('discharge_cancel')||(flow.get('discharge_bridge')||{}).active){cap=0;g.capA=0;g.reason='DISCHARGE_INTERLOCK';flow.set('charge_guard',g);}
let requested=Number(msg.payload);if(!Number.isFinite(requested)||requested<0)requested=0;
msg.payload=Math.min(requested,cap);
node.status({fill:cap===0?'red':'green',shape:'dot',text:reason+' | '+cap+' A'});
return msg;

const cfg=flow.get('solar_cfg');if(!cfg)return null;
const now=Date.now();let req=flow.get('discharge_request');
const h=flow.get('controller_health');
const required=['soc','battery_voltage','battery_current','grid_l1','grid_l2','grid_l3','bms_connected','bms_ccl','bms_cvl','bms_dcl','bms_min_cell','bms_max_cell','bms_temp'];
const sf=flow.get('source_faults')||{};
const fresh=required.every(k=>{const v=flow.get(k),ts=Number(flow.get(k+'_ts'));return v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))&&ts>0&&now-ts>=0&&now-ts<=20000&&!sf[k];});
const enabled=flow.get('controller_enabled')===true,paused=Number(flow.get('pause_until')||0)>now;
// A stale health report cannot renew an export lease.
if(req&&(!enabled||paused||!h?.ok||now-h.timestamp>15000||!fresh)){
 flow.set('discharge_request',null);flow.set('discharge_cancel',true);req=null;
}
let r={action:'status'};
if(flow.get('discharge_cancel'))r={action:'stop'};
else if(req)r={action:'pulse',...req};
// Base64 contains no shell metacharacters. No Telegram text reaches the exec command.
msg.payload=Buffer.from(JSON.stringify(r)).toString('base64');
return msg;

let r;try{r=JSON.parse(String(msg.payload));}catch(e){r={ok:false,error:'HELPER_INVALID_REPLY'};}
const now=Date.now(),old=flow.get('discharge_bridge')||{};
if(!r.boot){
 if(flow.get('discharge_request')||old.active){flow.set('discharge_cancel',true);flow.set('discharge_request',null);}
 flow.set('discharge_bridge',{...old,ok:false,error:r.error||'HELPER_UNAVAILABLE',timestamp:now});
 return {payload:now};
}
flow.set('discharge_bridge',{...r,timestamp:now});
if(r.restoring)flow.set('discharge_cancel',true);
if(!r.active){flow.set('discharge_request',null);if(!r.restoring)flow.set('discharge_cancel',false);}
if(r.requestError){flow.set('discharge_request',null);if(r.active)flow.set('discharge_cancel',true);}
if(old.active&&!r.active||r.requestError){
 const q=flow.get('controller_events')||[];
 q.push({ts:now,kind:'DISCHARGE_END',detail:'Descarcare fortata: '+(r.requestError||r.reason||r.error)+'. Revenire la ESS normal; acesta poate alimenta in continuare consumatorii din baterie.'});
 flow.set('controller_events',q.slice(-40));
}
node.status({fill:r.active?'yellow':r.ok?'green':'red',shape:'dot',text:r.active?'Descarcare '+r.currentA+' / '+r.amps+' A':r.reason||r.error});
return {payload:now};
